import json, numpy as np, cv2
from PIL import Image
from pathlib import Path
p=Path('/tmp/boxp441'); d=p/'v6/layout'; m=json.loads((d/'layout.json').read_text()); b=next(i for i in m['layers'] if i['id']=='body'); rect=b['rect']; orig=np.array(Image.open(p/'kohako/bust-smile.png').convert('RGB')); mask=np.array(Image.open(p/'v28-mask.png').convert('L')); under=np.array(Image.open(p/'aligned-v28.png').convert('RGB')); a=(mask>0).astype('uint8'); f=cv2.GaussianBlur(cv2.dilate(a,np.ones((5,5),np.uint8)).astype('float32'),(0,0),1.5); im=np.array(Image.open(d/b['image']['path']).convert('RGBA')); top,left=rect['top'],rect['left']; h,w=im.shape[:2]; t=f[top:top+h,left:left+w,None]; im[:,:,:3]=(im[:,:,:3]*(1-t)+under[top:top+h,left:left+w]*t).astype('uint8'); Image.fromarray(im).save(d/'body.png'); hair=np.zeros((650,680,4),dtype='uint8');hair[:,:,:3]=orig;hair[:,:,3]=mask;Image.fromarray(hair).save(d/'hair_outer.png'); n={'id':'hair_outer','name':'hair outer','image':{'path':'hair_outer.png','width':680,'height':650},'rect':{'left':0,'top':0,'width':680,'height':650},'tags':['hair','back']}; m['layers'].insert(m['layers'].index(b)+1,n);m['name']='kohako-v28-probe';(d/'layout.json').write_text(json.dumps(m,ensure_ascii=False,indent=2)); print('mask pixels',int(a.sum()))
